/**
 * Wraps a ConnectionRunnable in an AbstractFunction1 that applies the runnable to a given connection.
 * If an SQLException occurs, it throws a RuntimeException.
 *
 * @param block The ConnectionRunnable to be wrapped.
 * @return An AbstractFunction1 that applies the runnable to a connection.
 */
AbstractFunction1<Connection, BoxedUnit> connectionFunction(final ConnectionRunnable block) {
    return new AbstractFunction1<Connection, BoxedUnit>() {
        @Override
        public BoxedUnit apply(Connection connection) {
            try {
                block.run(connection);
                return BoxedUnit.UNIT;
            } catch (java.sql.SQLException e) {
                throw new RuntimeException("Connection runnable failed", e);
            }
        }
    };
}
