 * @return An AbstractFunction1 that applies the block and handles SQLExceptions.
 */
public AbstractFunction1<Connection, A> connectionFunction(final ConnectionCallable<A> block) {
    return new AbstractFunction1<Connection, A>() {
        @Override
        public A apply(Connection connection) {
            try {
                return block.call(connection);
            } catch (java.sql.SQLException e) {
                throw new RuntimeException("Connection callable failed", e);
            }
        }
    };
