public void start() throws IOException {
    // Initialize the server socket with the specified port and backlog
    serverSocket = new ServerSocket(listenPort, socketBacklog);
    // Enable address reuse
    serverSocket.setReuseAddress(true);
    // Create a fixed thread pool with the specified size
    executorService = Executors.newFixedThreadPool(threadPoolSize);
    // Set the server to running state
    running = true;
    // Continuously accept incoming connections
    while (running) {
        Socket socket = serverSocket.accept();
        // Disable keep-alive for the socket
        socket.setKeepAlive(false);
        // Execute the connection handling task in the thread pool
        executorService.execute(onSocketConnection(socket));
    }
    // Shutdown the thread pool when done
    executorService.shutdown();
}
