public static byte[] readBytes(final File file, final int count) throws IOException {
    // Check if the file exists and is a regular file
    checkExists(file);
    checkIsFile(file);

    // Get the file length and check if it exceeds the maximum array size
    long numToRead = file.length();
    if (numToRead >= Integer.MAX_VALUE) {
        throw new IOException("File is larger than max array size");
    }

    // Adjust the number of bytes to read if count is specified and valid
    if (count > NEGATIVE_ONE && count < numToRead) {
        numToRead = count;
    }

    // Create a byte array to hold the file content
    byte[] bytes = new byte[(int) numToRead];

    // Read the file content into the byte array using RandomAccessFile
    RandomAccessFile randomAccessFile = new RandomAccessFile(file, "r");
    randomAccessFile.readFully(bytes);
    randomAccessFile.close();

    // Return the byte array containing the file content
    return bytes;
}
```

