boolean isValidFile(ucar.unidata.io.RandomAccessFile raFile) {
    // Initialize the RandomAccessFile
    this.raFile = raFile;

    // Attempt to get the file length
    try {
        this.actualSize = raFile.length();
    } catch (IOException e) {
        return false;
    }

    // Read and process file headers and information
    try {
        this.readHeaderFromFile(raFile);
        this.handleFileInformation();
        this.handleProcessingInformation();
        this.handleSatelliteInformation();
        this.handleSensorInformation();
    } catch (IOException e) {
        return false;
    }

    // Return true if all operations are successful
