protected void update(CollectionUpdateType force) throws IOException {
    // This method may be called from a background thread or from the checkState() request thread.
    State localState;
    synchronized (lock) {
        if (first) {
            state = checkState();
            state.lastInvChange = System.currentTimeMillis();
            return;
        }
        // Perform the update in a local object
        localState = state.copy();
    }
    updateCollection(localState, force);
    localState.lastInvChange = System.currentTimeMillis();
    // Switch to live state
    synchronized (lock) {
        state = localState;
    }
}
