public boolean syncToDisk() {
    // If there is an output stream and the data is dirty, attempt to flush and sync to disk.
    if (outputStream != null && dirty) {
        try {
            // If the output stream is a FileChannel, force it to sync to disk.
            if (outputStream instanceof FileChannel) {
                FileChannel channel = (FileChannel) outputStream;
                channel.force(true);
            }
            dirty = false; // Mark the data as clean.
            return true; // Sync successful.
        } catch (Exception ex) {
            cleanupOutputStream(); // Clean up resources on error.
            return false; // Sync failed.
        }
    } else {
        return false; // No stream or data is not dirty.
    }
}
