public void connectionLost() {
    // Ensure only one thread attempts to reconnect
    synchronized (this) {
        if (reconnecting) return;
        reconnecting = true;
    }
    readerThread = null;
    boolean isConnected = false;
    if (!shutdown) {
        // Notify component of connection loss and shut it down
        component.shutdown();
    }
    while (!isConnected && !shutdown) {
        try {
            connect(host, port, subdomain);
            isConnected = true;
            if (shutdown) {
                disconnect();
            } else {
                start();
            }
        } catch (ComponentException e) {
